#!/usr/bin/env bash
# Ключевой арт для обложек Playgama — рисует Codex (по одной картинке, лимиты подписки).
# Логотип НЕ рисуем: настоящий накладывает tools/store_make.py (буквы у генератора гуляют).
cd "$(dirname "$0")/../.."
REFS="--ref art/chars/sheet.jpg --ref art/chars/sheet2.jpg --ref art/reel/atlas_preview.png --ref store/playgama/screenshots/5.jpg"
BASE="Обложка (key art) для детской казуальной браузерной 3D-игры «Spin the Chaos!»: блочные кубические персонажи в стиле \"сделано из кубиков\" (как на приложенных листах персонажей — свои оригинальные, не из чужих игр) убегают от весёлого хаоса на яркой арене-лужайке с деревянными ящиками, каменными блоками, кубическими деревьями и заборчиком. Хаос — существа и стихии с приложенного листа иконок: огненные акулы прыгают по траве, падают метеоры с огненным хвостом, гигантская зелёная лягушка, кубические зомби, бананы на земле, торнадо, пчёлы, слизь; по краю арены светится лава. В центре — главный герой (каштановые волосы, оранжево-красная футболка, синие штаны) в прыжке, с восторженным лицом; рядом ещё 3-4 персонажа с листов (ниндзя, викинг, кот, тыквоголовый, розоволосая девочка) бегут и смеются. Настроение — смешной безопасный хаос, никакой жестокости, крови и страха. Стиль: глянцевый 3D-рендер, мягкий свет, сочные насыщенные цвета (небесно-голубой, травяной зелёный, оранжевый огонь, розовый), лёгкая глубина резкости, динамичная композиция. БЕЗ какого-либо текста, букв, цифр, логотипов, интерфейса, рамок и игровых автоматов."
node tools/codex_image.cjs gen art/store/key_landscape.png "$BASE Формат ГОРИЗОНТАЛЬНЫЙ 3:2 (1536×1024). Верхние 40% по центру — относительно спокойное небо с облаками: туда потом ляжет логотип, важные персонажи ниже и по бокам." $REFS
node tools/codex_image.cjs gen art/store/key_portrait.png "$BASE Формат ВЕРТИКАЛЬНЫЙ 2:3 (1024×1536). Верхняя треть — спокойное небо с облаками под логотип; герой и хаос — в средней и нижней части." $REFS
node tools/codex_image.cjs gen art/store/key_square.png "$BASE Формат КВАДРАТНЫЙ 1:1 (1024×1024). Верхние 38% — спокойное небо под логотип; герой крупно в центре нижней половины." $REFS
ls -la art/store
